function progress(id,p,color){return '<div class="progress-item"><div class="ring" style="--p:'+p+';--ring:'+color+'"><strong>'+p+'%</strong></div><p>'+topicInfo[id].name+'</p></div>'}
function pageHead(kicker,title,lead){return '<div class="page-head"><div class="eyebrow">'+kicker+'</div><h2>'+title+'</h2><p class="lead">'+lead+'</p></div>'}
function study(){app.innerHTML=pageHead("STUDY GUIDE","Deep study with concept lineage","Trace each idea from its roots to its present civic meaning, then convert the insight into an exam cue.")+'<div class="study-index">'+Object.entries(studyGuide).map(([id,g])=>'<button class="card study-index-card" data-study="'+id+'"><span>'+topicInfo[id].icon+'</span><div><h3>'+g.title+'</h3><p>'+g.summary+'</p></div></button>').join("")+'</div>'}
function openStudy(id){const g=studyGuide[id];app.innerHTML=pageHead("STUDY GUIDE",topicInfo[id].icon+" "+g.title,g.summary)+'<section class="card study-insight"><div class="eyebrow">CORE INSIGHT</div><p>'+g.insight+'</p></section><div class="lineage">'+g.lineage.map((x,i)=>'<article class="lineage-step"><span>'+(i+1)+'</span><div><div class="eyebrow">LINEAGE '+(i+1)+'</div><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div></article>').join("")+'</div><section class="card study-cue"><div class="eyebrow">EXAM CUE</div><h3>'+g.cue+'</h3></section><div class="actions"><button class="primary" data-topic="'+id+'">Test this topic</button><button data-view="readings">Read long-form material</button><button data-view="study">Study another topic</button></div>'}
function readings(){app.innerHTML=pageHead("READINGS","In-depth learning material","Read for understanding, then retrieve what you learned.")+'<div class="cards">'+Object.entries(readingMaterial).map(([id,r])=>'<article class="card reading-card"><div class="eyebrow">'+topicInfo[id].icon+' '+id.toUpperCase()+'</div><h2>'+r.title+'</h2>'+r.paras.map(p=>'<p>'+p+'</p>').join("")+'<div class="actions"><button class="primary" data-topic="'+id+'">Check understanding</button><button data-lesson="'+id+'">Open lesson</button></div></article>').join("")+'</div>'}
function lesson(id){const t=topicInfo[id],n=conceptNotes[id];app.innerHTML=pageHead("DEEP LESSON",t.icon+" "+t.name,"Understand the idea, then retrieve it.")+'<div class="card" style="margin-bottom:18px"><h3>Why this matters</h3><p>'+n.why+'</p><h3>Example</h3><p>'+n.example+'</p><div class="visual">'+n.hook+'</div></div><div class="cards">'+lessonDetail[id].map(x=>'<article class="card"><h3>'+x[0]+'</h3><p>'+x[1]+'</p></article>').join("")+'</div><div class="actions"><button class="primary" data-topic="'+id+'">Check my recall</button><button data-view="learn">Back to Learning Hub</button></div>'}
function learn(){app.innerHTML=pageHead("LEARNING HUB","Learn the four testable areas","Build understanding first, then lock it in with visualisation and retrieval.")+'<div class="cards">'+Object.entries(topicInfo).map(([id,t])=>'<article class="card"><h3>'+t.icon+' '+t.name+'</h3><ul>'+t.items.map(x=>'<li>'+x+'</li>').join("")+'</ul><div class="actions"><button class="primary" data-lesson="'+id+'">Open lesson</button><button data-topic="'+id+'">Practise topic</button></div></article>').join("")+'</div>'}
function visual(){app.innerHTML=pageHead("VISUAL STORIES","Explore the ideas","Choose a story, tap through each concept, then complete its mini-check.")+'<div class="cards">'+Object.entries(visualStories).map(([id,v])=>'<button class="card visual-story-card" data-story="'+id+'"><div class="story-icon">'+v.icon+'</div><h3>'+v.title+'</h3><p>'+v.nodes.length+' interactive concepts + mini-check</p></button>').join("")+'</div>'}
function openStory(id){visualState={id,seen:[]};drawStory()}
function drawStory(){const v=visualStories[visualState.id];app.innerHTML=pageHead("VISUAL STORY",v.icon+" "+v.title,"Tap each node to reveal the meaning. Complete all nodes to unlock the mini-check.")+'<div class="story-track">'+v.nodes.map((n,i)=>'<button class="story-node '+(visualState.seen.includes(i)?"seen":"")+'" data-story-node="'+i+'"><span>'+(i+1)+'</span><b>'+n[0]+'</b></button>').join("")+'</div><div class="card story-detail" id="story-detail"><p class="hint">Choose a node to explore it.</p></div>'+(visualState.seen.length===v.nodes.length?'<div class="actions"><button class="primary" data-story-check>Unlock mini-check →</button></div>':"")}
function storyNode(i){if(!visualState.seen.includes(i))visualState.seen.push(i);const v=visualStories[visualState.id],n=v.nodes[i];drawStory();document.querySelector("#story-detail").innerHTML='<div class="eyebrow">CONCEPT '+(i+1)+'</div><h2>'+n[0]+'</h2><p class="lead">'+n[1]+'</p>'}
function storyCheck(){const v=visualStories[visualState.id],c=v.check;app.innerHTML=pageHead("MINI-CHECK",v.icon+" "+v.title,"Use retrieval, not recognition.")+'<section class="card quiz"><div class="question">'+c[0]+'</div><div class="choices">'+c[1].map((x,i)=>'<button class="choice" data-story-answer="'+i+'">'+x+'</button>').join("")+'</div><div id="story-feedback"></div></section>'}
function storyAnswer(i){const v=visualStories[visualState.id],c=v.check,ok=i===c[2],st=state.stats[visualState.id]||{c:0,t:0};st.t++;if(ok)st.c++;state.stats[visualState.id]=st;save();document.querySelectorAll("[data-story-answer]").forEach((b,n)=>{b.disabled=true;if(n===c[2])b.classList.add("correct");else if(n===i)b.classList.add("wrong")});document.querySelector("#story-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Visual story mastered":"✕ Review the story once more")+'</b><p>'+v.nodes.find(n=>n[0].toLowerCase().includes(c[1][c[2]].toLowerCase().split(" ")[0]))?.[1]+'</p><div class="actions"><button class="primary" data-view="visual">Choose another story</button><button data-story="'+visualState.id+'">Replay story</button></div></div>'}
function map(){app.innerHTML=pageHead("MAP LAB","States, territories & capitals","Explore the pairs, then test yourself with a scored capital challenge.")+'<div class="actions"><button class="primary" data-mapquiz>▶ Capital Challenge</button></div>'+'<div class="maplab"><div class="card">'+places.map((p,i)=>'<button class="statebtn" data-place="'+i+'">'+p[0]+'</button>').join("")+'</div><div class="card" id="place"><h3>Choose a state or territory</h3><p class="hint">Say the capital aloud before revealing it.</p></div></div>'}
function mapQuiz(){const items=shuffle(places.slice());session={mapItems:items,i:0,score:0,mode:"mapquiz"};drawMapQuiz()}
function drawMapQuiz(){const p=session.mapItems[session.i],opts=shuffle([p[1],...shuffle(places.filter(x=>x[1]!==p[1])).slice(0,3).map(x=>x[1])]);app.innerHTML=pageHead("CAPITAL CHALLENGE","What is the capital of "+p[0]+"?","Question "+(session.i+1)+" / "+session.mapItems.length+" · Score "+session.score)+'<section class="card quiz"><div class="choices">'+opts.map(x=>'<button class="choice" data-mapanswer="'+encodeURIComponent(x)+'">'+x+'</button>').join("")+'</div></section>'}
function mapAnswer(ans){const p=session.mapItems[session.i],ok=ans===p[1];if(ok)session.score++;const st=state.stats.people||{c:0,t:0};st.t++;if(ok)st.c++;state.stats.people=st;save();session.i++;if(session.i>=session.mapItems.length){app.innerHTML=pageHead("MAP CHALLENGE COMPLETE",session.score+" / "+session.mapItems.length,"Capital recall now contributes to Australia & its people mastery.")+'<button class="btn primary" data-view="map">Play again</button>';return}drawMapQuiz()}
function showPlace(i){document.querySelectorAll(".statebtn").forEach((b,n)=>b.classList.toggle("active",n===i));const p=places[i];document.querySelector("#place").innerHTML='<h3>'+p[0]+'</h3><p class="hint">What is the capital?</p><button class="btn primary" data-reveal="'+i+'">Reveal</button>'}
function revealPlace(i){const p=places[i];document.querySelector("#place").innerHTML='<h3>'+p[0]+'</h3><div class="capital">'+p[1]+'</div><p>Lock the pair together: <b>'+p[0]+' → '+p[1]+'</b></p>'}
function cards(){const now=Date.now(),due=flashcards.map((c,i)=>({i,d:state.reviews[i]||0})).filter(x=>x.d<=now).sort((a,b)=>a.d-b.d);if(due.length&&!flipped)cardIndex=due[0].i;const c=flashcards[cardIndex],known=!!state.known[cardIndex];app.innerHTML=pageHead("FLASHCARDS","Build recall","Think first, reveal second, then rate your recall.")+'<section class="card flash"><div class="eyebrow">'+c[2].toUpperCase()+' · '+(cardIndex+1)+' / '+flashcards.length+'</div><div class="face">'+(flipped?c[1]:c[0])+'</div><p class="hint">'+(flipped?"Answer":"Retrieve it before you tap reveal.")+'</p><div class="actions" style="justify-content:center"><button class="primary" data-flip>'+(flipped?"Show question":"Reveal answer")+'</button>'+(flipped?'<button data-rate="0">× Review again</button><button data-rate="1">✓ I know it</button>':"")+'</div><p class="'+(known?"good":"hint")+'">'+(known?"✓ Marked known":"Not mastered yet")+'</p></section><div class="actions" style="justify-content:center"><button data-prev>← Previous</button><button data-next>Next →</button></div>'}
function adaptiveReinforce(){const misses=Object.keys(state.missed).filter(k=>state.missed[k]>0),weak=Object.keys(topicInfo).sort((a,b)=>pct(a)-pct(b))[0];let q=questions.filter(x=>misses.includes(x[1]));q=q.concat(questions.filter(x=>x[0]===weak&&!q.includes(x)));startSession(shuffle(q).slice(0,10),"adaptive")}
function practice(){app.innerHTML=pageHead("REINFORCE","Targeted practice","Choose a topic or train everything together.")+'<div class="cards">'+Object.entries(topicInfo).map(([id,t])=>'<button class="card" data-topic="'+id+'" style="text-align:left;cursor:pointer"><h3>'+t.icon+' '+t.name+'</h3><p>Focused retrieval drill</p></button>').join("")+'</div><div class="actions"><button class="primary" data-adaptive>Adaptive drill</button><button data-topic="all">Mixed drill</button><button data-view="mistakes">Review mistakes</button></div>'}
function mistakes(){const ks=Object.keys(state.missed).filter(k=>state.missed[k]>0).sort((a,b)=>state.missed[b]-state.missed[a]);if(!ks.length){app.innerHTML=pageHead("MISTAKES","Clean slate ✓","No unresolved mistakes yet. Keep practising to generate useful signals.")+'<button class="btn primary" data-view="practice">Start practice</button>';return}app.innerHTML=pageHead("MISTAKES","Turn errors into assets","The questions below are currently your highest-value review opportunities.")+'<div class="cards">'+ks.map(k=>'<article class="card"><div class="eyebrow">'+state.missed[k]+' MISS'+(state.missed[k]>1?"ES":"")+'</div><h3>'+k+'</h3></article>').join("")+'</div><div class="actions"><button class="primary" data-action="mistakes">Train my mistakes</button></div>'}
function readiness(){const ms=state.mocks.slice(-5),recent3=ms.slice(-3),consistent=recent3.length===3&&recent3.every(m=>m.score>=15&&m.values===5),valueStreak=[...state.mocks].reverse().findIndex(m=>m.values!==5),streak=valueStreak<0?state.mocks.length:valueStreak;const topics=Object.keys(topicInfo).map(id=>({id,p:pct(id)})),unresolved=Object.values(state.missed).filter(n=>n>0).length,mastery=Math.round(topics.reduce((a,x)=>a+x.p,0)/topics.length),ready=consistent&&mastery>=80&&pct("values")>=90&&unresolved===0;app.innerHTML=pageHead("EXAM READINESS","Your readiness cockpit","Passing once is useful. Consistent performance is the stronger signal.")+'<div class="cards"><article class="card"><div class="eyebrow">READINESS SIGNAL</div><h2 class="'+(consistent?"good":"bad")+'">'+(ready?"CONSISTENTLY READY":"BUILDING READINESS")+'</h2><p>'+(ready?"Mocks, topic mastery, Values and mistake recovery all meet the readiness standard.":"Readiness now combines mock consistency, 80%+ topic mastery, strong Values performance and zero unresolved mistakes.")+'</p></article><article class="card"><div class="eyebrow">VALUES STREAK</div><h2>'+streak+'</h2><p>consecutive mock'+(streak===1?"":"s")+' with 5/5 Values</p></article></div><div class="card" style="margin-top:18px"><h3>Topic heatmap</h3><div class="progress-grid">'+topics.map(x=>progress(x.id,x.p,x.p>=85?"#28e178":x.p>=75?"#f4c651":"#ff6767")).join("")+'</div></div><div class="card" style="margin-top:18px"><h3>Recent mock history</h3>'+(ms.length?ms.reverse().map((m,i)=>'<p><b class="'+(m.pass?"good":"bad")+'">'+m.score+'/20 · Values '+m.values+'/5</b> <span class="hint">Attempt '+(state.mocks.length-i)+'</span></p>').join(""):'<p class="hint">No mock exams completed yet.</p>')+'<div class="actions"><button class="primary" data-view="mock">Take a mock exam</button><button data-view="practice">Target weak areas</button></div></div>'}
function games(){const best=Number(localStorage.getItem("atest-quest-best")||0);app.innerHTML=pageHead("CITIZENSHIP QUEST","A real learning game","Clear four missions with three lives. Correct answers earn XP and streak multipliers.")+'<section class="card quest-hero"><div><div class="eyebrow">BEST SCORE</div><h2>'+best+' XP</h2><p>4 missions · 3 lives · streak bonuses</p></div><button class="btn primary" data-quest-start>▶ Start Quest</button></section><div class="cards">'+Object.entries(sortGames).map(([id,g],i)=>'<article class="card"><div class="eyebrow">MISSION '+(i+1)+'</div><h3>'+["🪪","🏛️","⚖️","🤝"][i]+' '+g.title+'</h3><p>'+g.items.length+' challenges</p></article>').join("")+'</div>'}
function startQuest(){quest={mission:0,index:0,lives:3,xp:0,streak:0,maxStreak:0};loadMission()}
function loadMission(){const ids=Object.keys(sortGames);if(quest.mission>=ids.length)return winQuest();quest.id=ids[quest.mission];quest.items=shuffle(sortGames[quest.id].items.slice());quest.index=0;drawQuest()}
function drawQuest(){const g=sortGames[quest.id],item=quest.items[quest.index],mult=Math.min(3,1+Math.floor(quest.streak/3));app.innerHTML='<section class="quest-shell"><div class="quest-hud"><div><small>MISSION</small><b>'+(quest.mission+1)+'/4</b></div><div><small>LIVES</small><b class="lives">'+("♥ ".repeat(quest.lives)||"0")+'</b></div><div><small>STREAK</small><b>🔥 '+quest.streak+'</b></div><div><small>MULTIPLIER</small><b>×'+mult+'</b></div><div><small>XP</small><b>'+quest.xp+'</b></div></div><div class="card quest-card"><div class="eyebrow">'+g.title.toUpperCase()+' · '+(quest.index+1)+'/'+quest.items.length+'</div><div class="question">'+item[0]+'</div><div class="choices">'+g.bins.map(x=>'<button class="choice" data-quest-bin="'+encodeURIComponent(x)+'">'+x+'</button>').join("")+'</div><div id="quest-feedback"></div></div></section>'}
function questAnswer(bin){const item=quest.items[quest.index],ok=bin===item[1],mult=Math.min(3,1+Math.floor(quest.streak/3));if(ok){quest.streak++;quest.maxStreak=Math.max(quest.maxStreak,quest.streak);quest.xp+=100*mult}else{quest.lives--;quest.streak=0}const questTopic={citizenship:"rights",levels:"government",powers:"government",valuesort:"values"}[quest.id];const qs=state.stats[questTopic]||{c:0,t:0};qs.t++;if(ok)qs.c++;state.stats[questTopic]=qs;save();document.querySelectorAll("[data-quest-bin]").forEach(x=>{x.disabled=true;const v=decodeURIComponent(x.dataset.questBin);if(v===item[1])x.classList.add("correct");else if(v===bin)x.classList.add("wrong")});document.querySelector("#quest-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"+"+(100*mult)+" XP":"♥ Life lost")+'</b><p><strong>'+item[0]+'</strong> → '+item[1]+'</p><button class="btn primary" id="quest-next">'+(quest.lives?"Continue":"Results")+'</button></div>';document.querySelector("#quest-next").onclick=()=>{if(!quest.lives)return loseQuest();quest.index++;if(quest.index>=quest.items.length){quest.xp+=250;quest.mission++;return loadMission()}drawQuest()}}
function winQuest(){const best=Math.max(quest.xp,Number(localStorage.getItem("atest-quest-best")||0));localStorage.setItem("atest-quest-best",best);const rank=quest.xp>=5000?"Federation Master":quest.xp>=3500?"Civic Champion":"Citizen Scholar";app.innerHTML=pageHead("QUEST COMPLETE","🏆 "+rank,quest.xp+" XP · Best streak "+quest.maxStreak)+'<section class="card quest-result"><div class="quest-trophy">🏆</div><h2>All missions cleared</h2><div class="actions"><button class="primary" data-quest-start>Play again</button><button data-view="readiness">Readiness</button></div></section>'}
function loseQuest(){const best=Math.max(quest.xp,Number(localStorage.getItem("atest-quest-best")||0));localStorage.setItem("atest-quest-best",best);app.innerHTML=pageHead("QUEST OVER","Recharge and return",quest.xp+" XP · Best streak "+quest.maxStreak)+'<section class="card quest-result"><div class="quest-trophy">🛡️</div><h2>Three lives used</h2><p>Review the missed concepts and come back for the clear.</p><div class="actions"><button class="primary" data-quest-start>Retry quest</button><button data-view="learn">Review lessons</button></div></section>'}
function game(){gameState={score:0,streak:0,round:0,current:null};nextGame()}
function nextGame(){if(gameState.round>=10){app.innerHTML=pageHead("KEYWORD FORGE","Run complete ⚡","You scored "+gameState.score+" / 10.")+'<div class="card"><h3>Best streak: '+gameState.streak+'</h3><p>Run it again to make the language automatic.</p><div class="actions"><button class="primary" data-view="game">Play again</button><button data-view="learn">Review lessons</button></div></div>';return}const correct=keywords[Math.floor(Math.random()*keywords.length)],others=shuffle(keywords.filter(x=>x[0]!==correct[0])).slice(0,3),opts=shuffle([correct,...others]);gameState.current=correct;app.innerHTML=pageHead("KEYWORD FORGE","Match the keyword","Round "+(gameState.round+1)+" / 10 · Score "+gameState.score)+'<section class="card quiz"><div class="question">'+correct[1]+'</div><div class="choices">'+opts.map(x=>'<button class="choice" data-keyword="'+encodeURIComponent(x[0])+'">'+x[0]+'</button>').join("")+'</div><div id="game-feedback"></div></section>'}
function gameAnswer(term){const ok=term===gameState.current[0];if(ok){gameState.score++;gameState.streak++}else gameState.streak=0;gameState.round++;document.querySelectorAll("[data-keyword]").forEach(b=>{b.disabled=true;const t=decodeURIComponent(b.dataset.keyword);if(t===gameState.current[0])b.classList.add("correct");else if(t===term)b.classList.add("wrong")});document.querySelector("#game-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Forged":"✕ Reforge")+'</b><p><strong>'+gameState.current[0]+'</strong> → '+gameState.current[1]+'</p><button class="btn primary" id="game-next">Next</button></div>';document.querySelector("#game-next").onclick=nextGame}
function values(){start("values")}
function mock(){if(mockTimer)clearInterval(mockTimer);const valuesQ=questions.filter(q=>q[0]==="values");const other=questions.filter(q=>q[0]!=="values");const picked=[];for(let i=0;i<15;i++)picked.push(other[i%other.length]);for(let i=0;i<5;i++)picked.push(valuesQ[i%valuesQ.length]);startSession(shuffle(picked),"mock");mockEnds=Date.now()+45*60*1000;startMockClock()}
function startMockClock(){if(mockTimer)clearInterval(mockTimer);mockTimer=setInterval(()=>{if(!session||session.mode!=="mock"){clearInterval(mockTimer);mockTimer=null;return}const left=Math.max(0,mockEnds-Date.now()),el=document.querySelector("#mock-clock");if(el)el.textContent=Math.floor(left/60000)+":"+String(Math.floor((left%60000)/1000)).padStart(2,"0");if(left<=0){clearInterval(mockTimer);mockTimer=null;finish()}},1000)}
function start(mode){let q=mode==="all"?questions.slice():questions.filter(x=>x[0]===mode);startSession(shuffle(q),mode)}
function startSession(q,mode){session={q,i:0,score:0,mode,valuesCorrect:0};drawQuestion()}
function drawQuestion(){const q=session.q[session.i];app.innerHTML='<section class="card quiz"><div class="eyebrow">'+(session.mode==="mock"?'MOCK EXAM · <span id="mock-clock">45:00</span>':"REINFORCEMENT")+' · '+(session.i+1)+' / '+session.q.length+'</div><div class="question">'+q[1]+'</div><div class="choices">'+q[2].map((x,i)=>'<button class="choice" data-answer="'+i+'">'+String.fromCharCode(65+i)+'. '+x+'</button>').join("")+'</div><div id="feedback"></div></section>'}
function answer(i){const q=session.q[session.i],ok=i===q[3];if(ok){session.score++;if(q[0]==="values")session.valuesCorrect++;state.missed[q[1]]=0}else state.missed[q[1]]=(state.missed[q[1]]||0)+1;const s=state.stats[q[0]]||{c:0,t:0};s.t++;if(ok)s.c++;state.stats[q[0]]=s;save();document.querySelectorAll(".choice").forEach((b,n)=>{b.disabled=true;if(n===q[3])b.classList.add("correct");else if(n===i)b.classList.add("wrong")});document.querySelector("#feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Correct":"✕ Not yet")+'</b><p>'+q[4]+'</p><button class="btn primary" id="next">'+(session.i===session.q.length-1?"Finish":"Next")+'</button></div>';document.querySelector("#next").onclick=()=>{session.i++;session.i>=session.q.length?finish():drawQuestion()}}
function finish(){if(mockTimer){clearInterval(mockTimer);mockTimer=null}if(session.mode==="mock"){const pass=session.score>=15&&session.valuesCorrect===5;state.mocks.push({score:session.score,values:session.valuesCorrect,pass,date:Date.now()});state.mocks=state.mocks.slice(-10);save();app.innerHTML=pageHead("MOCK EXAM RESULT",pass?"Pass standard met ✓":"Not yet","Pass requires at least 15/20 overall and 5/5 values.")+'<div class="cards"><div class="card"><h3>'+session.score+' / 20</h3><p>Overall score</p></div><div class="card"><h3>'+session.valuesCorrect+' / 5</h3><p>Values score</p></div></div><div class="actions"><button class="primary" data-view="home">Back to dashboard</button><button data-view="mock">Retake</button></div>';return}const p=Math.round(session.score/session.q.length*100);app.innerHTML=pageHead("SESSION COMPLETE",session.score+" / "+session.q.length,p+"% correct")+'<div class="actions"><button class="primary" data-view="practice">Train again</button><button data-view="mistakes">Review mistakes</button></div>'}
function recommended(){const r=nextAction();if(r.topic)start(r.topic);else route(r.view)}
function weakest(){const ids=Object.keys(topicInfo);ids.sort((a,b)=>pct(a)-pct(b));start(ids[0])}
function trainMistakes(){const ks=Object.keys(state.missed).filter(k=>state.missed[k]>0);const q=questions.filter(x=>ks.includes(x[1]));if(q.length)startSession(q,"mistakes");else practice()}
function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1])}
function route(view){document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.view===view));({home:dashboard,learn,readings,study,visual,map,cards,game,games,practice,mistakes,values,mock,readiness}[view]||dashboard)();window.scrollTo({top:0,behavior:"smooth"})}
document.addEventListener("click",e=>{const v=e.target.closest("[data-view]"),t=e.target.closest("[data-topic]"),a=e.target.closest("[data-answer]");if(v)return route(v.dataset.view);if(t)return start(t.dataset.topic);const l=e.target.closest("[data-lesson]");if(l)return lesson(l.dataset.lesson);if(a)return answer(+a.dataset.answer);const stg=e.target.closest("[data-study]");if(stg)return openStudy(stg.dataset.study);const story=e.target.closest("[data-story]");if(story)return openStory(story.dataset.story);const sn=e.target.closest("[data-story-node]");if(sn)return storyNode(+sn.dataset.storyNode);if(e.target.closest("[data-story-check]"))return storyCheck();const sa=e.target.closest("[data-story-answer]");if(sa)return storyAnswer(+sa.dataset.storyAnswer);if(e.target.closest("[data-mapquiz]"))return mapQuiz();const ma=e.target.closest("[data-mapanswer]");if(ma)return mapAnswer(decodeURIComponent(ma.dataset.mapanswer));if(e.target.closest("[data-adaptive]"))return adaptiveReinforce();if(e.target.closest("[data-quest-start]"))return startQuest();const qb=e.target.closest("[data-quest-bin]");if(qb)return questAnswer(decodeURIComponent(qb.dataset.questBin));const sg=e.target.closest("[data-sortgame]");if(sg)return startSort(sg.dataset.sortgame);const bin=e.target.closest("[data-bin]");if(bin)return sortAnswer(decodeURIComponent(bin.dataset.bin));const kw=e.target.closest("[data-keyword]");if(kw)return gameAnswer(decodeURIComponent(kw.dataset.keyword));const p=e.target.closest("[data-place]"),r=e.target.closest("[data-reveal]");if(p)return showPlace(+p.dataset.place);if(r)return revealPlace(+r.dataset.reveal);if(e.target.closest("[data-flip]")){flipped=!flipped;return cards()}if(e.target.closest("[data-next]")){cardIndex=(cardIndex+1)%flashcards.length;flipped=false;return cards()}if(e.target.closest("[data-prev]")){cardIndex=(cardIndex-1+flashcards.length)%flashcards.length;flipped=false;return cards()}const rate=e.target.closest("[data-rate]");if(rate){const yes=rate.dataset.rate==="1";state.known[cardIndex]=yes;state.reviews[cardIndex]=Date.now()+(yes?3*86400000:10*60000);save();cardIndex=(cardIndex+1)%flashcards.length;flipped=false;return cards()}const act=e.target.closest("[data-action]");if(e.target.closest("#next-best"))return recommended();if(act?.dataset.action==="weak")return weakest();if(act?.dataset.action==="mistakes")return trainMistakes()});
route("home");